  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Cada uma inicia sessão neste perfil a partir do dispositivo ou do gestor de palavras-passe que a guarda. Toca numa para lhe mudar o nome ou a remover.',
