  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Para este dispositivo, uma chave de segurança, um gestor de palavras-passe ou o teu telemóvel através do código QR do próprio navegador. Primeiro confirma que és tu.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Deixa de poder iniciar sessão neste perfil. Um dispositivo que já tenha sessão iniciada com ela continua com sessão iniciada. Se a perdeste, usa «Terminar sessão em todos os dispositivos».',
  'It is your only way in, so it cannot be removed until there is another.': 'É a tua única forma de entrar, por isso não pode ser removida enquanto não houver outra.',
  'Last used {0}': 'Usada pela última vez a {0}',
  'Make a new code': 'Criar um novo código',
  'Name, e.g. Work laptop': 'Nome, p. ex. Portátil do trabalho',
  'None yet. Add one and sign in without your password.': 'Ainda nenhuma. Adiciona uma e inicia sessão sem a tua palavra-passe.',
  'Passkey added': 'Passkey adicionada',
  'Passkey removed': 'Passkey removida',
  'Passkey {0}': 'Passkey {0}',
  'Passkeys': 'Passkeys',
  'Remove passkey': 'Remover passkey',
  'Remove this passkey?': 'Remover esta passkey?',
  'Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Digitaliza isto com o outro dispositivo, ou abre lá o openGym e introduz o código no ecrã de início de sessão. Funciona uma vez, durante {0} minutos.',
  'That code is wrong, already used or expired. Make a new one on your other device.': 'Esse código está errado, já foi usado ou expirou. Cria um novo no teu outro dispositivo.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Este navegador não consegue confirmar com a tua passkey. Faz isto num dispositivo que tenha uma.',
  'First confirm that it is you.': 'Primeiro confirma que és tu.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Este perfil não tem nenhuma passkey e este servidor não aceita palavras-passe, por isso nada aqui pode confirmar que és tu. Pede ajuda ao teu administrador.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Este navegador não consegue criar passkeys, por isso não pode ser adicionado com um código. Abre a ligação num navegador que consiga.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Este navegador tem sessão iniciada como «{0}». Adicioná-lo a «{1}» termina aqui a sessão de «{0}».',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Este código é de outro perfil que também se chama «{0}», não daquele com que este navegador tem sessão iniciada. Adicionar aí o navegador termina aqui a sessão do teu perfil.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Continua só se este código vier de um dispositivo teu. Este navegador fica então com sessão iniciada em «{0}», e o que registares aqui vai para esse perfil.',
  'This code has expired.': 'Este código expirou.',
  'This device already has a passkey for this profile.': 'Este dispositivo já tem uma passkey para este perfil.',
  'This passkey already belongs to a profile.': 'Esta passkey já pertence a um perfil.',
  'This profile already has as many passkeys as it can hold.': 'Este perfil já tem todas as passkeys que pode ter.',
  'Use a code from your other device': 'Usar um código do teu outro dispositivo',
  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': 'Recebes um código com o qual o teu telemóvel ou outro computador pode criar uma passkey para este perfil. Primeiro confirma que és tu.',
