  'Add time': 'Aumentar o tempo',
  'Targets stay where you set them.': 'Os objetivos ficam como os definires.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Se completares todas as repetições em todas as séries, o peso sobe. Falhas repetidas provocam uma descarga.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Duas séries normais e uma final até à falha. Bate o objetivo nessa série e o peso sobe (a dobrar se dobrares as repetições). Uma falha recua 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Sobe ao longo de um intervalo de repetições com o mesmo peso. Atinge o topo do intervalo em todas as séries e o peso sobe, com as repetições de volta ao mínimo.',
  'Hold every set for the full duration and the target goes up.': 'Aguenta todas as séries o tempo completo e o objetivo sobe.',
  'Nothing logged yet, so this session sets the baseline.': 'Ainda nada registado, por isso esta sessão define o ponto de partida.',
  'Held every set for the full time. Target goes up by {0}s.': 'Aguentaste todas as séries o tempo todo. O objetivo sobe {0} s.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0} sessões seguidas abaixo do alvo. Recua para {1} s e volta a subir.',
  'Came up short last time. Same target again.': 'Ficaste aquém da última vez. O mesmo objetivo outra vez.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Topo do intervalo em todas as séries. Mais {0} {1}, de volta a {2} repetições.',
