  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'Topo do intervalo em todas as séries. Menos {0} {1} de ajuda, de volta a {2} repetições.',
  'Missed reps. {0} {1} of help while you build back up.': 'Repetições falhadas. {0} {1} de ajuda enquanto voltas a subir.',
