  'Exact {0}': '{0} exato',
  'Clear rating': 'Limpar avaliação',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'O RIR conta as repetições que ficaram no depósito; o RPE lê o mesmo esforço numa escala de 10, por isso RPE ≈ 10 − RIR. Escolhe aquele em que já pensas.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'A linha destacada é onde cai a maioria das séries de trabalho. As séries já registadas mantêm a sua escala, e mais nada lê o valor, por isso a progressão e o 1RM estimado não mudam.',
