  'What leaves this phone': 'O que sai deste telemóvel',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'O teu servidor não tem o Treinador ativado. Pergunta ao administrador, ou usa a tua própria chave aqui em baixo.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'O teu servidor corre o Treinador com o fornecedor que o administrador configurou. Nada de novo sai deste telemóvel para além do que já é sincronizado.',
