  // --- AI Coach chat ---
  'A local model can take longer.': 'Um modelo local pode demorar mais.',
  'All optional. The more the Coach knows, the less it guesses.': 'Tudo opcional. Quanto mais o Treinador souber, menos tem de adivinhar.',
  'Almost there': 'Quase lá',
  'Avoid: {0}': 'Evitar: {0}',
  'Before we start': 'Antes de começarmos',
  'Building your plan…': 'A criar o teu plano…',
  'Discarded. Tell me what was off and I will build a different one.': 'Descartado. Diz-me o que não encaixou e eu faço outro.',
  'Done! Your plan is back to how it was before my last changes.': 'Feito! O teu plano voltou ao que era antes das minhas últimas alterações.',
