  'Build me a fresh plan from my answers.': 'Faz-me um plano novo a partir das minhas respostas.',
  'Experience': 'Experiência',
  'Goal, days, equipment, limits': 'Objetivo, dias, equipamento, limitações',
  'Have a look at my training and tell me what you would change.': 'Vê o meu treino e diz-me o que mudarias.',
  'Here is what I am working with:': 'É com isto que conto:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Olá, sou o teu Treinador. Construo o teu plano a partir das tuas respostas e ajusto-o com base no que realmente registas. Nada muda até dizeres.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'Vi tudo e neste momento não mudaria nada. Continua assim, e pergunta-me de novo depois de mais umas sessões.',
  'I understand, let’s go': 'Percebi, vamos a isso',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'Importado! {0} rotinas estão no teu plano e a tua semana está definida. Até à próxima sessão.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'Importado! {0} rotinas estão no teu plano. A tua semana não muda; agenda-as quando quiseres.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Cria o teu plano a partir de algumas respostas e ajusta-o com base no que registas. Nunca muda nada sem a tua autorização, e podes anular cada alteração.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Rotinas, exercícios, séries e repetições, o teu horário semanal e as definições de progressão.',
  'Your logged training': 'O teu treino registado',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'As séries que registaste no período de revisão: pesos, repetições, tempos, avaliações de esforço, quanto tempo duraram as sessões e as tuas notas das sessões.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'As pesagens do mesmo período e o teu peso alvo, se o definiste.',
