  'Some changes on this device have not reached your server.': 'Algumas alterações neste dispositivo ainda não chegaram ao teu servidor.',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Tenta de novo, ou exporta primeiro uma cópia. Se continuares mesmo assim, fica uma cópia destas alterações neste dispositivo até ele voltar a ligar-se a este servidor com esta conta. Aí são novamente adicionadas.',
