  'Save changes': 'Guardar alterações',
  "Don't save": 'Não guardar',
  'Keep editing': 'Continuar a editar',
  'This workout was deleted on another device. Your edits are still here.': 'Este treino foi eliminado noutro dispositivo. As tuas alterações continuam aqui.',
  'Close editor': 'Fechar editor',
  'Editing a saved workout. Date and duration stay unchanged.': 'Estás a editar um treino guardado. A data e a duração permanecem inalteradas.',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Uma puxada para cada empurrão, para os ombros ficarem equilibrados.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Uma rotação de dois dias em três sessões por semana, construída à volta do equipamento que indicaste. Primeiro os exercícios compostos, uma puxada para cada empurrão e sobreposição suficiente entre os dias para que nada fique duas semanas sem ser treinado.',
  'Based on the training already in this demo profile.': 'Com base no treino que já existe neste perfil de demonstração.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'O peso corporal está parado há quatro semanas e o objetivo é ganhar. Isso é um problema de cozinha, não de treino. Não é o plano que o está a travar.',
  'Demo': 'Demo',
  'Demo data reset': 'Dados da demo repostos',
  'Direct arm work, since you asked for it.': 'Trabalho direto de braços, já que o pediste.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Todas as séries principais deste exercício ficaram em RPE 9,5 ou mais durante três sessões e o peso não mexeu. Trocar o movimento durante quatro semanas costuma desbloquear essa estagnação mais depressa do que insistir no mesmo.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Dados de exemplo, guardados só neste navegador. Mexe à vontade e muda o que quiseres.',
  'Full body A': 'Corpo inteiro A',
  'Full body B': 'Corpo inteiro B',
  'Horizontal pressing, the other half of the session.': 'Empurrão horizontal, a outra metade da sessão.',
  'Live demo. Everything stays in this browser.': 'Demo ao vivo. Tudo fica neste navegador.',
  'No training history yet, so starting conservatively.': 'Ainda não há histórico de treino, por isso começamos com prudência.',
  'Passkey sign-in, sync across your devices, your own data.': 'Início de sessão com passkey, sincronização entre os teus dispositivos, os teus próprios dados.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Repõe o plano, os treinos e as pesagens de exemplo como estavam no início.',
  'Reset': 'Repor',
  'Reset demo data': 'Repor dados da demo',
  'Reset demo data?': 'Repor os dados da demo?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Revisto como pediste. Tudo o que não puseste em causa está exatamente como estava.',
  'Same pattern, higher reps than day A.': 'O mesmo padrão, mais repetições do que no dia A.',
  'Self-host it in a minute →': 'Aloja-o tu mesmo num minuto →',
  'Self-host openGym': 'Alojar o openGym por conta própria',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'As sessões estão a durar cerca de quinze minutos a mais. Este é o exercício acessório que menos perde com uma série a menos.',
  'Start the demo': 'Iniciar a demo',
  'The main lower-body driver, where most of the strength comes from.': 'O motor principal da parte inferior do corpo, de onde vem a maior parte da força.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Os mesmos padrões, variações diferentes: sobreposição suficiente para progredir, diferença suficiente para não cansar.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Primeiro os dois grandes padrões de membros inferiores e de empurrar, enquanto estás fresco.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Esta demo corre inteiramente no teu navegador com dados de exemplo. Nada é enviado para lado nenhum. O início de sessão com passkey e a sincronização entre os teus dispositivos vêm com o servidor openGym, que obténs alojando-o tu mesmo.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Três coisas que vale a pena mudar e uma que vale a pena saber. Tudo o resto está a funcionar: o agachamento e as puxadas estão ambos a progredir como previsto.',
  'Vertical pressing.': 'Empurrão vertical.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Mudaste esta sessão para sábado três semanas seguidas. Mais vale o plano dizê-lo do que estares sempre a alterá-lo.',
  'You’re in the demo': 'Estás na demo',
  // --- a past workout: drop-sets, supersets, its exercises' history, copy as text ---
  'Copy as text': 'Copiar como texto',
