  'Performance report': 'Relatório de desempenho',
  'Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.': 'O teu treino em papel: totais, gráficos, novos recordes e cada série. Emoldura, imprime ou envia ao teu treinador.',
