  // --- app tour (components/Tour.jsx) ---
  "A one-minute walk around the app": "Uma volta de um minuto pela app",
  "A practice workout": "Um treino a fingir",
  "Backups, imports and syncing with your own server.": "Cópias de segurança, importações e sincronização com o teu servidor.",
  "Body map": "Mapa do corpo",
  "Catch your breath": "Recupera o fôlego",
  "Done with a set? Tick it. Go on, try it.": "Série feita? Marca-a. Vá, experimenta.",
  "Filter it down": "Afina a lista",
  "Find any exercise": "Encontra qualquer exercício",
  "Finish line": "Meta",
  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": "Terminar guarda a sessão e faz avançar os teus pesos. Este treino a fingir simplesmente desaparece.",
  "Finish the tour?": "Acabar a visita?",
  "Finish your workout first, then the tour is all yours.": "Termina primeiro o teu treino, depois a visita é toda tua.",
  "Kilos or pounds, and the language you like best.": "Quilos ou libras, e a língua de que mais gostas.",
  "Let’s go": "Vamos a isso",
  "Make it yours": "À tua maneira",
  "Muscles at a glance": "Músculos num relance",
  "Narrow the list by body part, type or the equipment you have.": "Filtra a lista por parte do corpo, tipo ou o equipamento que tens.",
  "No thanks": "Não, obrigado",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "Escolhe um exercício para ver as melhores séries, o máximo estimado e para onde vai.",
  "Pointing at: {0}": "Aponta para: {0}",
  "Practice run": "Sessão de treino",
  "Programmes and sharing": "Programas e partilha",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "Programas, planos iniciais e partilhar um plano com um amigo estão atrás deste botão.",
  "Records": "Recordes",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Horário diz quando, Rotinas diz o quê. Cria as tuas ou pega num plano inicial.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Milhares de exercícios na tua língua. Marca os favoritos com estrela e sobem para o topo.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Vê que músculos trabalharam e quais ainda precisam de descanso. Toca num para ver detalhes.",
  "Show me": "Mostra-me",
  "Show the tour again": "Ver a visita outra vez",
  "Skip tour": "Saltar visita",
  "Step {0} of {1}": "Passo {0} de {1}",
  "Swipe a set": "Desliza uma série",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "Desliza uma série para o lado para a copiar ou apagar. O número dela abre ainda mais.",
  "The big Start button": "O grande botão Começar",
  "The little body shows what each day works, so leg day can’t hide.": "O corpinho mostra o que cada dia trabalha, assim o dia de pernas não se esconde.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "O descanso começa sozinho. Junta tempo, ou salta-o se te sentires herói.",
  "The ⋯ menu": "O menu ⋯",
  "Theme, accent colour and what Home shows.": "Tema, cor de destaque e o que o Início mostra.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Este é a fingir, nada fica guardado. Cada linha é uma série: peso, depois repetições. Toca num número para o mudar.",
  "Tick it off": "Marca-a",
  "Today at a glance": "Hoje num relance",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "A sessão de hoje está aqui. Um toque e estás a levantar. Num dia de descanso diz isso mesmo, sem culpa.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Treina em dias fixos, ou põe as rotinas em ciclo: a próxima espera por ti.",
  "Want a 1-minute tour?": "Uma visita de 1 minuto?",
  "Week or rotation": "Semana ou rotação",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "Mostramos-te o melhor nos ecrãs a sério. Podes sair quando quiseres.",
  "Workout settings, layouts, notes and extra exercises hide in here.": "Definições do treino, esquemas, notas e mais exercícios escondem-se aqui.",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "Treinos, sequências e tudo o que já levantaste. Enche-se à medida que treinas.",
  "You stopped halfway. Want to see the rest?": "Paraste a meio. Queres ver o resto?",
  "Your data, your backups": "Os teus dados, as tuas cópias",
  "Your progress": "O teu progresso",
  "Your routines": "As tuas rotinas",
  "You’re set": "Está tudo pronto",
