  'Pick a day': 'Escolhe um dia',
  'With pictures': 'Com imagens',
  'A small picture next to each exercise, like a plan from the gym.': 'Uma pequena imagem ao lado de cada exercício, como um plano do ginásio.',
  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Isto vive na app openGym do telemóvel: Apple Health no iPhone, Health Connect no Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Os webhooks são enviados pelo teu próprio servidor openGym, por isso é preciso um. Liga este dispositivo em Conta.",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "Os webhooks estão desligados neste servidor. Adiciona INTEGRATIONS=webhook ao .env e reinicia-o.",
  "The MCP server runs next to your own openGym server and reads your data there.": "O servidor MCP corre ao lado do teu servidor openGym e lê lá os teus dados.",
  "Only what you switch on talks to anything. The rest stays out of your way.": "Só o que ligares fala com alguma coisa. O resto não te incomoda.",
  "Could not reach your server": "Não foi possível contactar o teu servidor",
  "Tap to try again": "Toca para tentar de novo",
  "Disconnect {0}?": "Desligar {0}?",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "O openGym deixa de escrever e ler. O que já escreveu pode ficar lá como dados teus, ou sair.",
  "Works with": "Funciona com",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "Não é preciso outra ligação: escrevem no {0} e o openGym lê de lá.",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "Não é preciso outra ligação: escrevem no Apple Health ou no Health Connect e a app openGym do telemóvel lê de lá.",
  "{0} has no direct line to openGym, and it does not need one.": "{0} não tem ligação direta ao openGym, e não precisa.",
  "How it gets here": "Como chega aqui",
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": "{0} guarda no Apple Health no iPhone ou no Health Connect no Android. O openGym lê de lá.",
  "What openGym reads": "O que o openGym lê",
  "What it does not do": "O que não faz",
  "Workouts logged in openGym go to the health store, not back into {0} itself.": "Os treinos registados no openGym vão para o arquivo de saúde, não de volta para o {0}.",
  "Set up {0}": "Configurar {0}",
