  "Open a workout": "Abrir um treino",
  "Optional: your own picture or clip of the setup. Handy for that one weird machine.": "Opcional: a tua própria foto ou vídeo da montagem. Dá jeito para aquela máquina esquisita.",
  "Pick a backup file and it’s all back.": "Escolhe um ficheiro de cópia e volta tudo.",
