  "Search finds your exercises like any other, and they go into routines and workouts the same way.": "A pesquisa encontra os teus exercícios como qualquer outro, e eles entram em rotinas e treinos da mesma forma.",
  "Settings are on Home": "As Definições estão no Início",
  "Share weigh-ins and workouts with the phone’s health app.": "Partilha pesagens e treinos com a app de saúde do telemóvel.",
  "So the equipment filter and your gym profiles know about it.": "Para que o filtro de equipamento e os teus perfis de ginásio o conheçam.",
  "Spreadsheet": "Folha de cálculo",
  "Strong, Hevy, FitNotes, GymMane or Apple Health body weight: import their export here.": "Strong, Hevy, FitNotes, GymMane ou peso corporal do Apple Health: importa aqui a exportação deles.",
  "Syncing lives under your account. Tap back to Settings.": "A sincronização está na tua conta. Volta às Definições.",
  "Syncing your devices through your own openGym server lives under your account. No server? Everything still works on this device.": "A sincronização dos teus dispositivos através do teu próprio servidor openGym está na tua conta. Sem servidor? Tudo continua a funcionar neste dispositivo.",
  "Tap Add and pick your new routine. The loop runs in that order.": "Toca em Adicionar e escolhe a tua nova rotina. A rotação segue essa ordem.",
  "Tap Add exercise to pick what goes in.": "Toca em Adicionar exercício para escolher o que entra.",
  "Tap All weigh-ins.": "Toca em Todas as pesagens.",
  "Tap Create exercise when it looks right. Or Next to just look around.": "Toca em Criar exercício quando estiver bem. Ou em Seguinte para só espreitar.",
  "Tap New routine. It stays a draft until you save it.": "Toca em Nova rotina. Fica como rascunho até a guardares.",
  "Tap Schedule to put it on a day.": "Toca em Horário para a pôr num dia.",
  "Tap a weekday and choose your new routine. Two on one day works too.": "Toca num dia da semana e escolhe a tua nova rotina. Duas no mesmo dia também dá.",
  "Tap an exercise any time to change sets, reps or weight. The arrows reorder, the link makes a superset.": "Toca num exercício quando quiseres para mudar séries, repetições ou peso. As setas reordenam, a ligação faz uma supersérie.",
