  "Tap back.": "Volta atrás.",
  "Tap it.": "Toca aí.",
  "Tap one to set its sets, reps and weight, or + to take the usual. Close the list when you’re done.": "Toca num para definir séries, repetições e peso, ou em + para o habitual. Fecha a lista quando acabares.",
  "That’s a plan": "Isto é um plano",
  "That’s the lot": "É tudo",
  "The bin deletes one, and Undo pops up right after. Wrong number? Log that day again and the new one wins.": "O caixote do lixo apaga uma, e Anular aparece logo a seguir. Número errado? Regista esse dia outra vez e a nova ganha.",
  "The exercise library": "A biblioteca de exercícios",
  "The gear": "A roda dentada",
  "The phone saves a fresh backup by itself after changes.": "O telemóvel guarda sozinho uma cópia fresca depois de cada alteração.",
  "They live under Stats. Tap it.": "Estão nas Estatísticas. Toca aí.",
  "They’re on Home. Tap it.": "Estão no Início. Toca aí.",
  "This is your real plan now, if you want it. Save keeps it. Skip and it was never here.": "Agora este é o teu plano a sério, se o quiseres. Guardar fica com ele. Saltar e nunca existiu.",
  "This one is for real: we build a routine together and it lands in your plan when you tap Save. Bail before that and nothing stays behind.": "Esta é a sério: construímos uma rotina juntos e ela vai para o teu plano quando tocares em Guardar. Se desistires antes, não fica nada.",
  "Tutorials": "Tutoriais",
  "Up one level": "Subir um nível",
  "Want more? Each of these is a short guided run. You’ll find them again in Settings → About & updates.": "Queres mais? Cada um destes é um passeio guiado curto. Voltas a encontrá-los em Definições → Sobre e atualizações.",
  "We swapped in a practice copy with a pretend workout and weigh-in. Poke at anything, nothing here sticks.": "Pusemos uma cópia de ensaio com um treino e uma pesagem a fingir. Mexe no que quiseres, aqui nada fica.",
