  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Isto é público para toda a gente neste servidor: qualquer pessoa com conta aqui pode vê-lo, experimentá-lo e copiá-lo. O teu nome e a data vão sempre com ele. Partilha só o que é teu: algo que fizeste, gravaste ou tens o direito de passar a outros. As imagens e animações de exercícios da biblioteca integrada são licenciadas e nunca podem ser partilhadas. Podes deixar de partilhar quando quiseres; as cópias que outros já tiraram ficam com eles.",
