  "Link": "Ligar",
  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "Liga a tua conta {0} e entra com ela a partir de agora. As tuas passkeys continuam a funcionar. Primeiro, uma verificação rápida de que és mesmo tu.",
  "Linked. You can sign in with {0} from now on.": "Ligado. A partir de agora podes entrar com {0}.",
  "Linked. {0} signs you in here.": "Ligado. O {0} faz-te entrar aqui.",
