  "This profile is already linked to a {0} account.": "Este perfil já está ligado a uma conta {0}.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "Este perfil está ligado à tua conta {0}: com sessão iniciada lá, tens sessão iniciada aqui.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Este servidor é só por convite e o {0} sozinho não chega. Pergunta a quem o gere.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "Neste servidor toda a gente entra com {0}. És novo aqui? Ao entrares, o teu perfil é criado.",
  "This server signs people in with {0}.": "Este servidor faz as pessoas entrar com {0}.",
  "Too many attempts. Try again in a minute.": "Demasiadas tentativas. Tenta outra vez daqui a um minuto.",
  "Unlink": "Desligar",
  "Unlinked. {0} no longer signs you in here.": "Desligado. O {0} já não te faz entrar aqui.",
  "or use a pairing code": "ou usa um código de emparelhamento",
  "{0} could not be reached. Try again in a moment.": "Não foi possível contactar {0}. Tenta outra vez daqui a pouco.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "O {0} é a única forma de entrar neste perfil, por isso continua ligado. Adiciona primeiro uma passkey.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "O {0} deixou-te entrar, mas este servidor só aceita certos grupos. Pede a quem o gere para te adicionar.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "O {0} devolveu algo que não conseguimos verificar, por isso ninguém entrou. Se voltar a acontecer, a página de administração diz porquê.",
  "Backups: {0}": "Alternativas: {0}",
