  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Gordura corporal e massa magra, tal como a tua balança as guardou. Aparecem em Medidas corporais e nunca se misturam com o que registas.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Gordura corporal, massa magra, massa óssea, água corporal e metabolismo basal, tal como a tua balança os guardou. Aparecem em Medidas corporais e nunca se misturam com o que registas.",
