  "After a year": "Após um ano",
  "After {0} days": "Após {0} dias",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "Copia-o agora: é a única vez que o openGym o mostra. Trata-o como uma palavra-passe.",
  "Ends": "Termina",
