  "A buzz for each phase": "Uma vibração para cada fase",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "Uma cópia de tudo, uma vez por dia, numa pasta só tua: Nextcloud, ownCloud, um NAS, qualquer coisa que fale WebDAV. O teu servidor, de mais ninguém.",
