  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "O cardio sobe como aquilo que foi: uma corrida, uma volta de bicicleta, remo. A força como Treino com pesos, com cada série na descrição.",
  "Change server or password": "Mudar servidor ou palavra-passe",
  "Check the connection": "Verificar a ligação",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Liga o Strava uma vez a partir do openGym num navegador, com sessão iniciada no teu servidor. Depois os treinos sobem a partir do servidor, seja qual for o dispositivo onde os registas.",
