  "No openGym backups in that folder yet.": "Ainda não há cópias do openGym nessa pasta.",
  "No tempo": "Sem cadência",
  "Open in my calendar app": "Abrir na minha app de calendário",
  "Pick one. You choose whether it replaces what is here or merges with it.": "Escolhe uma. Tu decides se substitui o que está aqui ou se junta tudo.",
  "Reconnect": "Voltar a ligar",
  "Rep {0} of {1}": "Rep {0} de {1}",
  "Restore from a backup": "Restaurar de uma cópia",
  "Same as the rest ({0})": "Igual aos outros ({0})",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "Segundos para cada parte de uma rep: descer, pausa, subir, contrair. 3-1-1-0 é três a descer, um em baixo, um a subir e logo a seguinte.",
  "Show finished workouts too": "Mostrar também treinos concluídos",
  "Strava connected. Your next workout goes up by itself.": "Strava ligado. O próximo treino sobe sozinho.",
  "Strava disconnected": "Strava desligado",
  "Strava is listening": "O Strava está à escuta",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "O Strava está desligado neste servidor. Regista uma app na Strava API, depois junta strava a INTEGRATIONS e o STRAVA_CLIENT_ID e STRAVA_CLIENT_SECRET ao .env, e reinicia.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Os envios para o Strava saem do teu próprio servidor openGym, por isso precisas de um. Liga este dispositivo a ele em Conta.",
  "Strength workouts too": "Treinos de força também",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "Subscreve este link na tua app de calendário. Quem o tiver vê o teu plano, por isso guarda-o para ti.",
  "Tempo": "Cadência",
  "Tempo for this set": "Cadência desta série",
  "Tempo {0}": "Cadência {0}",
  "Tempo {0}, start the guide": "Cadência {0}, iniciar o guia",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "O link do calendário é servido pelo teu próprio servidor openGym, por isso precisas de um. Liga este dispositivo a ele em Conta.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "O link deixa de funcionar de imediato. O que o teu calendário já mostra pode ficar até atualizar.",
  "The old link stops working, and every calendar that uses it needs the new one.": "O link antigo deixa de funcionar, e cada calendário que o usa vai precisar do novo.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "A palavra-passe fica neste dispositivo, no armazenamento seguro. Nunca é sincronizada nem entra numa cópia.",
  "The server cannot show this link again. Make a new one.": "O servidor não consegue mostrar este link outra vez. Cria um novo.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "Este dispositivo deixa de fazer cópias e esquece a palavra-passe. As cópias que já estão na pasta ficam lá.",
  "Tick the set": "Marcar a série",
  "Turn off": "Desligar",
  "Turn off the calendar feed?": "Desligar o feed de calendário?",
  "Up as fast as you can. The guide gives it one quick second.": "A subir o mais rápido que conseguires. O guia dá-lhe um segundo rapidinho.",
  "Uploading": "A enviar",
  "User name": "Nome de utilizador",
  "WebDAV backup": "Cópia WebDAV",
  "When the app is open, at most once a day, on this device.": "Com a app aberta, no máximo uma vez por dia, neste dispositivo.",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "As tuas sessões planeadas no Apple Calendar, Google Calendar ou Outlook, sempre atualizadas. Um link privado que só o teu calendário conhece.",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "O teu servidor esquece a sessão e deixa de enviar. O que está no Strava fica, e a app do Strava mantém o acesso até o removeres em strava.com.",
  "{0} s per rep, a guide in the workout counts it for you.": "{0} s por rep, um guia no treino conta por ti.",
  "{0} s under tension": "{0} s sob tensão",
  "{0} s under tension. Lovely and slow.": "{0} s sob tensão. Lindo e lento.",
  "Backups & calendar": "Cópias e calendário",
  "A copy every day in your own Nextcloud or any WebDAV folder.": "Uma cópia todos os dias no teu próprio Nextcloud ou em qualquer pasta WebDAV.",
  "The full backup, once a day while the app is open, and whenever you tap Back up now.": "A cópia completa, uma vez por dia com a app aberta, e sempre que tocas em Fazer cópia agora.",
  "Restore it on a new phone in two taps.": "Restaura-a num telemóvel novo em dois toques.",
