  // --- promises-146: progression rules, shoulder heads and lats, bench, own media ---,
  "Steady double progression": "Dupla progressão constante",
  "Undulating days": "Dias ondulantes",
  "Shorter rests": "Descansos mais curtos",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Sobe por um intervalo de repetições, uma de cada vez. Todas as séries têm de chegar ao objetivo antes de ele subir, e no topo do intervalo o peso sobe.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Cada sessão roda: um dia médio com as tuas repetições, um dia pesado com menos e um leve com mais. Os pesos vêm do teu máximo estimado, por isso sobem à medida que ficas mais forte.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Mesmo peso, um pouco menos de descanso sempre que todas as séries saem limpas. No descanso mais curto o peso sobe e o descanso recomeça.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Todas as séries chegaram a {0}. Mesmo peso, {1} repetições desta vez.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Nem todas as séries chegaram a {0} ainda. Mesmo peso e objetivo outra vez (faltam {1} de {2}).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Todas as séries limpas. Mesmo peso com menos {0} s de descanso: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Limpo no descanso mais curto. Menos {0} {1} de ajuda, descanso de volta a {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Limpo no descanso mais curto. Mais {0} {1}, descanso de volta a {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Parado há {0} sessões. Mesmo peso com mais descanso: {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Falhaste repetições da última vez. Mesmo peso e descanso outra vez (faltam {0} de {1}).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Dia pesado: {0} repetições com {1} {2}, a partir do teu máximo estimado de {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Dia leve: {0} repetições com {1} {2}, a partir do teu máximo estimado de {3} {2}.",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Dia médio: {0} repetições com {1} {2}, a partir do teu máximo estimado de {3} {2}.",
