  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Esta versão do openGym vem sem a ligação ao Garmin, porque a parte da Garmin não é open source. As versões da App Store, do Google Play e do GitHub têm-na.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "O Garmin Connect não está neste telemóvel. Instala-o, emparelha lá o teu relógio e volta aqui.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "O Garmin Connect precisa de uma atualização antes de o openGym poder falar com o teu relógio.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Não foi possível chegar ao Garmin Connect. Tenta de novo daqui a pouco.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Escolhe o teu Garmin no Garmin Connect e os teus treinos aparecem no pulso.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "O Garmin Connect ainda não conhece nenhum relógio. Emparelha primeiro o teu lá.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "O openGym está no teu Garmin. As séries que registas no pulso chegam aqui.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "O openGym está no teu Garmin. Põe-se a par assim que o relógio estiver ao alcance.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "O teu Garmin está aqui, mas o openGym ainda não. Instala-o e abre-o uma vez no relógio.",
