  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Se ninguém responder, termina sozinho e nunca deita nada fora. O fim é a tua última série mais o descanso, para o tempo continuar honesto. Podes reabri-lo no histórico durante um dia. O relógio também pergunta.",
  "Never asks and never ends one by itself.": "Nunca pergunta e nunca termina nada sozinho.",
  "The default. Long enough for a chat at the water fountain.": "O padrão. Dá para uma conversa junto ao bebedouro.",
  "Asks the moment your phone walks out of your gym, then wraps up.": "Pergunta assim que o telemóvel sai do teu ginásio e depois fecha.",
  "Needs the gym reminder: {0}.": "Precisa do lembrete do ginásio: {0}.",
